from edition_config import EDITION_ID,EDITION_LABEL,DATE_WEEKDAY,DATE_WEEKDAY_SHORT,DATE_DOTTED,YEAR
import html
from urllib.parse import quote
e=lambda v:html.escape(str(v),quote=True)
SECTIONS=[('pesquisa','Pesquisa'),('clinica','Clínica'),('saude-publica','Saúde pública'),('formacao','Formação'),('inovacao','Inovação'),('instituicoes','Instituições')]
def header(p='',article=False,section=None):
 home=p or './'
 links=f'<a href="{home}">Primeira página</a>'+''.join(f'<a href="{p}editorias/{key}/"'+((' aria-current="location"' if article else ' aria-current="page"') if key==section else '')+f'>{name}</a>' for key,name in SECTIONS)+f'<a href="{p}fontes/">Fontes</a><a href="{p}edicao/">Edições</a>'
 masthead=(f'<div class="masthead compact-masthead"><a href="{home}" aria-label="THE MED TIMES — página inicial"><img class="masthead-logo" src="{p}assets/masthead.svg" width="1200" height="154" alt="THE MED TIMES"></a><span>Medicina, ciência e descobertas.</span></div>' if article else f'<div class="masthead"><div class="edition-box"><em>Ciência para ler.<br>Medicina para pensar.</em><span class="smallcaps">Uma edição para quem<br>não para de aprender</span></div><a href="{home}" aria-label="THE MED TIMES — página inicial"><img class="masthead-logo" src="{p}assets/masthead.svg" width="1200" height="154" alt="THE MED TIMES"><p class="tagline">Medicina, ciência e descobertas.</p></a><div class="masthead-right"><span class="smallcaps">{EDITION_LABEL}</span><strong>{DATE_WEEKDAY_SHORT}</strong><span>Uma leitura crítica<br>do mundo da saúde.</span></div></div>')
 options=''.join(f'<option value="{key}">{name}</option>' for key,name in SECTIONS)
 return f'''<a class="skip" href="#conteudo">Pular para o conteúdo</a><div class="paper"><header class="site-header"><div class="topline"><span>Medicina em perspectiva</span><a href="{p}sobre/">Nosso compromisso editorial ↗</a></div>{masthead}<div class="datebar"><span>Ano I · Nº {EDITION_ID}</span><strong>{DATE_WEEKDAY}</strong><span class="desktop">Edição digital · Em português</span><span>Leitura em português</span></div><div class="navigation"><div class="nav-tools"><button type="button" class="menu-toggle" aria-expanded="false" aria-controls="section-navigation">Cadernos <span aria-hidden="true">☰</span></button><button type="button" class="search-toggle" aria-expanded="false" aria-controls="search-panel"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><circle cx="10" cy="10" r="6.5"/><path d="m15 15 6 6"/></svg>Buscar</button></div><nav id="section-navigation" class="navrow" aria-label="Cadernos e páginas do jornal">{links}</nav></div><form id="search-panel" class="search-panel" action="{home}" hidden><div class="search-panel-heading"><label for="search">Buscar na edição {EDITION_ID}</label><span>Somente as 96 matérias desta edição</span></div><div class="search-query"><input id="search" name="q" type="search" placeholder="Tema, palavra ou descoberta…" autocomplete="off"><button type="submit">Buscar</button></div><div class="search-filters"><label for="search-section">Caderno<select id="search-section" name="secao"><option value="">Todos os cadernos</option>{options}</select></label><label for="search-type">Tipo de conteúdo<select id="search-type" name="tipo"><option value="">Todos os tipos</option><option value="noticia">Notícia</option><option value="guia">Guia / referência</option><option value="analise">Análise</option></select></label></div><p class="search-status">Use palavras e filtros. Resultados ordenados por relevância, com prioridade para o título.</p></form></header>'''
def footer(p=''):
 return f'''<footer class="footer"><div class="footer-top"><a class="footer-brand" href="{p or './'}">THE MED TIMES</a><nav aria-label="Rodapé"><a href="{p}sobre/">Sobre o jornal</a><a href="{p}sobre/#politica">Política editorial</a><a href="{p}edicao/">Edição de {DATE_DOTTED}</a><a href="{p}assets/FONT-LICENSE.txt">Licenças tipográficas</a></nav></div><div class="footer-bottom"><p>© {YEAR} THE MED TIMES · Medicina, ciência e descobertas.</p><p>Jornal digital. Conteúdo educativo, não substitui avaliação médica.</p></div></footer></div>'''
def shell(title,body,p='',description='Medicina, ciência e descobertas. Jornal de leitura crítica sobre saúde, pesquisa e formação médica.',article=False,section=None):
 return f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#FFFFFF"><title>{e(title)} — THE MED TIMES</title><meta name="description" content="{e(description)}"><link rel="icon" href="{p}assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{p}styles-reading.css"><script src="{p}app-reading.js" defer></script></head><body data-edition="{EDITION_ID}" data-section="{section or ''}"{' class="article-page"' if article else ''}>{header(p,article,section)}{body}{footer(p)}</body></html>'''
